  require("SUCCESS".equals(state)&&p.publication().equals(receipt.get("publicationId"))&&p.confirmation().equals(receipt.get("confirmationId"))&&p.businessKey().equals(receipt.get("businessKey"))&&p.logicalHash().equals(receipt.get("logicalRequestHash"))&&p.executionHash().equals(receipt.get("executionRequestHash"))&&token.executionId().equals(receipt.get("executionId"))&&token.executionNo()==((Number)receipt.get("executionNo")).longValue()&&p.actor().enterpriseId().equals(receipt.get("actorId"))&&p.library().equals(receipt.get("libraryId"))&&p.folder().equals(receipt.get("folderId"))&&p.payloadHash().equals(receipt.get("payloadSha256"))&&client.identities().get("clientId").equals(receipt.get("clientId")),PROVENANCE_UNAVAILABLE);
